;; =============================================================
;; OPEN.BIN - Title/opening data archive (seen resident at 0x80180000)
;; =============================================================

;; --- Bitmap text (generated by tools/title_gfx.py, TIM pixel data at the same offset) ---
; "Memory card checking" box: TIM 0x25840 (8bpp, VRAM 832,0), pixel data 0x25A60, 64 KiB
.org OPEN_ADDR + 0x25A60
    .incbin "build/gfx/open_25840.bin"

;; "SLOT 1 / SLOT 2" buttons (+ tab of the save list): TIM 0x474C0 (4bpp 256x32, VRAM 704,256), pixel data 0x47520, 4096 bytes
.org OPEN_ADDR + 0x47520
    .incbin "build/gfx/open_474C0.bin"

